import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';


function Validation() {
    const navigate = useNavigate();
  // State variables for input fields
  const [emailOrPhone, setEmailOrPhone] = useState('');
  const [password, setPassword] = useState('');

  // Refs for input fields
  const emailOrPhoneRef = useRef(null);
  const passwordRef = useRef(null);

  // Handler for form submission
  const handleLogin = async (event) => {
    event.preventDefault();

    // Input validation logic
    if (!emailOrPhone || !password) {
      return;
    }

    try {
      // Fetch user data from your JSON file or backend API
      const response = await fetch('http://localhost:3000'); // Replace with your server URL
      const users = await response.json();

      // Check if the provided credentials match any user in the database
      const validUser = users.find(user => user.emailOrPhone === emailOrPhone && user.password === password);

      if (validUser) {
        navigate('homePage');
      }
    } catch (error) {
      return;
    }
  };

  return (
    <div className="login-container">
      <h2>Log In</h2>
      <form onSubmit={handleLogin}>
        <div className="input-group">
          <label htmlFor="emailOrPhone">Email or Phone</label>
          <input
            type="text"
            id="emailOrPhone"
            ref={emailOrPhoneRef}
            value={emailOrPhone}
            onChange={(event) => setEmailOrPhone(event.target.value)}
          />
        </div>
        <div className="input-group">
          <label htmlFor="password">Password</label>
          <input
            type="password"
            id="password"
            ref={passwordRef}
            value={password}
            onChange={(event) => setPassword(event.target.value)}
          />
        </div>
        <button type="submit">Log In</button>
      </form>
    </div>
  );
}

export default Validation;
